function findConflicts(slot: Slot, candidates: Slot[]): SlotDto[] {
  return candidates
    .filter(
      (candidate) =>
        candidate.id !== slot.id && slotsOverlap(slot, candidate),
    )
    .map(toConflictDto);
}
```

Overlap rule: `A.start < B.end && A.end > B.start` (touching ends don’t count).

